	comfy.SetValue(in, "on_exclusion_overlap", a.OnExclusionOverlap, "fill", true, true)
	comfy.SetBool(in, "send_unmasked_copy", a.SendUnmaskedCopy, true, true, true)
	comfy.SetValue(in, "timeout_seconds", a.TimeoutSeconds, int64(180), true, true)
	comfy.SetValue(in, "rerun_nonce", a.RerunNonce, int64(0), true, true)
	comfy.SetBool(in, "dry_run", a.DryRun, false, true, true)
